class Solution {
public:
    vector<vector<int>> highestRankedKItems(vector<vector<int>>& grid, vector<int>& pricing, vector<int>& start, int k) {
        int m=grid.size(),n=grid[0].size();
        queue<pair<int,int>> q; vector<vector<int>> dist(m,vector<int>(n,-1));
        q.push({start[0],start[1]});dist[start[0]][start[1]]=0;
        vector<array<int,4>> items; int dr[4]={1,-1,0,0},dc[4]={0,0,1,-1};
        while(!q.empty()) {
            auto p=q.front();q.pop();int r=p.first,c=p.second;
            if(grid[r][c]>=pricing[0] && grid[r][c]<=pricing[1])
                items.push_back({dist[r][c],grid[r][c],r,c});
            for(int t=0;t<4;++t) {
                int x=r+dr[t],y=c+dc[t];
                if(x>=0&&x<m&&y>=0&&y<n&&grid[x][y]!=0&&dist[x][y]<0) {
                    dist[x][y]=dist[r][c]+1;q.push({x,y});
                }
            }
        }
        sort(items.begin(),items.end()); vector<vector<int>> ans;
        for(int i=0;i<(int)items.size()&&i<k;++i) ans.push_back({items[i][2],items[i][3]});
        return ans;
    }
};
